effect.shader:
const int MAXIMO_DE_ANEIS = 12;

/**
 * A cor acumulada no pixel pelos anéis vivos.
 *
 * Cada anel k nasce em `k * spacing`, vive `duracao` segundos e caminha com
 * `speed`. A idade no relógio deste quadro é `fract(.)`, o raio é
 * `idade * speed`, e o pixel pega o que estiver mais perto do seu raio.
 */
void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    vec2 p = (acScreenNorm - centerAt) * vec2(acAspect, 1.0);
    float d = length(p);

    float duracao = spacing * float(count);

    int quantos = clamp(int(count + 0.5), 1, MAXIMO_DE_ANEIS);
    float melhorMiolo = 0.0;
    float melhorHalo = 0.0;

    for (int k = 0; k < MAXIMO_DE_ANEIS; k++) {
        if (k >= quantos) break;

        float fase = acTime / max(duracao, 1e-4) + float(k) / float(quantos);
        float idade = fract(fase) * duracao;
        float raio = idade * speed;

        // O anel nasce fino, afina um pouco mais com a idade e some: o desvanecer
        // combina a idade (tempo de vida) com o raio (distância), que é o que dá
        // o ar de sinal se perdendo.
        float velhice = idade / max(duracao, 1e-4);
        float opacidade = pow(1.0 - clamp(velhice, 0.0, 1.0), max(fade, 1e-4));

        float esp = thickness * (1.0 - 0.4 * velhice);
        float distanciaAoAnel = abs(d - raio);

        float miolo = (1.0 - smoothstep(0.0, esp, distanciaAoAnel)) * opacidade;
        float halo = exp(-distanciaAoAnel / max(esp * 7.0, 1e-5)) * glow * opacidade;

        melhorMiolo = max(melhorMiolo, miolo);
        melhorHalo = max(melhorHalo, halo);
    }

    vec3 cor = ringColor.rgb * (melhorMiolo + melhorHalo);
    float alfa = clamp(max(melhorMiolo, melhorHalo * 0.7), 0.0, 1.0) * ringColor.a;

    vec4 desenhado = vec4(cor, alfa);
    float saidaAlfa = desenhado.a + original.a * (1.0 - desenhado.a);
    vec3 saidaCor = saidaAlfa > 0.0
        ? (desenhado.rgb * desenhado.a + original.rgb * original.a * (1.0 - desenhado.a)) / saidaAlfa
        : vec3(0.0);

    fragColor = vec4(saidaCor, saidaAlfa);
}
